// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes32 role, address account) public {
        vm.assume(role != 0x00);
        vm.assume(account != address(c));
        vm.assume(account != address(this));
        vm.assume(account != address(0));
        vm.assume(role != keccak256("TIMELOCK_ADMIN_ROLE"));
        vm.assume(role != keccak256("PROPOSER_ROLE"));
        vm.assume(role != keccak256("EXECUTOR_ROLE"));
        assertTrue(c.hasRole(c.TIMELOCK_ADMIN_ROLE(), address(c)) == true);
    }
}
